buffer_from_file(struct buffer *buffer, FILE *fp)
{
 struct buffer_list *last = &buffer->first;
 size_t count = 0;

 for (;;)
 {
 size_t r = fread(last->buffer+count, 1/*size*/,
 (sizeof last->buffer)-count, fp);

 if (r > 0)
 {
         count += r;

 if (count >= sizeof last->buffer)
 {
            assert(count == sizeof last->buffer);
            count = 0;

 if (last->next == NULL)
 {
               last = buffer_extend(last);
 if (last == NULL)
 return MEMORY;
 }

 else
               last = last->next;
 }
 }

 else /* fread failed - probably end of file */
 {
 if (feof(fp))
 {
            buffer->last = last;
            buffer->end_count = count;
 return 0; /* no error */
 }

 /* Some kind of funky error; errno should be non-zero */
 return errno == 0 ? ERANGE : errno;
 }
 }
},0,False

bool RenderFrameHostManager::CanSubframeSwapProcess(
    const GURL& dest_url,
    SiteInstance* source_instance,
    SiteInstance* dest_instance,
    bool was_server_redirect) {
  DCHECK(!source_instance || !dest_instance);

  if (!SiteIsolationPolicy::AreCrossProcessFramesPossible())
    return false;

  GURL resolved_url = dest_url;
  if (url::Origin(resolved_url).unique()) {
    if (source_instance) {
      resolved_url = source_instance->GetSiteURL();
    } else if (dest_instance) {
      resolved_url = dest_instance->GetSiteURL();
    } else {
      if (!was_server_redirect)
        return false;
    }
  }

  if (!IsRendererTransferNeededForNavigation(render_frame_host_.get(),
                                             resolved_url)) {
    DCHECK(!dest_instance ||
           dest_instance == render_frame_host_->GetSiteInstance());
    return false;
  }

  return true;
 },0,False

void __local_bh_enable_ip(unsigned long ip, unsigned int cnt)
{
	WARN_ON_ONCE(in_irq());
	lockdep_assert_irqs_enabled();
#ifdef CONFIG_TRACE_IRQFLAGS
	local_irq_disable();
#endif
	/*
	 * Are softirqs going to be turned on now:
	 */
	if (softirq_count() == SOFTIRQ_DISABLE_OFFSET)
		trace_softirqs_on(ip);
	/*
	 * Keep preemption disabled until we are done with
	 * softirq processing:
	 */
	preempt_count_sub(cnt - 1);

	if (unlikely(!in_interrupt() && local_softirq_pending())) {
		/*
		 * Run softirq if any pending. And do it in its own stack
		 * as we may be calling this deep in a task call stack already.
		 */
		do_softirq();
	}

	preempt_count_dec();
#ifdef CONFIG_TRACE_IRQFLAGS
	local_irq_enable();
#endif
	preempt_check_resched();
},0,False

