static bool ldap_decode_control_wrapper(void *mem_ctx, struct asn1_data *data,
					struct ldb_control *ctrl, DATA_BLOB *value)
{
	DATA_BLOB oid;

	if (!asn1_start_tag(data, ASN1_SEQUENCE(0))) {
		return false;
	}

	if (!asn1_read_OctetString(data, mem_ctx, &oid)) {
		return false;
	}
	ctrl->oid = talloc_strndup(mem_ctx, (char *)oid.data, oid.length);
	if (!ctrl->oid) {
		return false;
	}

	if (asn1_peek_tag(data, ASN1_BOOLEAN)) {
		bool critical;
		if (!asn1_read_BOOLEAN(data, &critical)) {
			return false;
		}
		ctrl->critical = critical;
	} else {
		ctrl->critical = false;
	}

	ctrl->data = NULL;

	if (!asn1_peek_tag(data, ASN1_OCTET_STRING)) {
		*value = data_blob(NULL, 0);
		goto end_tag;
	}

	if (!asn1_read_OctetString(data, mem_ctx, value)) {
		return false;
	}

end_tag:
	if (!asn1_end_tag(data)) {
		return false;
	}

	return true;
},0,False

status_t SampleIterator::findSampleTimeAndDuration(
 uint32_t sampleIndex, uint32_t *time, uint32_t *duration) {
 if (sampleIndex >= mTable->mNumSampleSizes) {
 return ERROR_OUT_OF_RANGE;
 }

 while (sampleIndex >= mTTSSampleIndex + mTTSCount) {
 if (mTimeToSampleIndex == mTable->mTimeToSampleCount) {
 return ERROR_OUT_OF_RANGE;
 }

        mTTSSampleIndex += mTTSCount;
        mTTSSampleTime += mTTSCount * mTTSDuration;

        mTTSCount = mTable->mTimeToSample[2 * mTimeToSampleIndex];
        mTTSDuration = mTable->mTimeToSample[2 * mTimeToSampleIndex + 1];

 ++mTimeToSampleIndex;
 }

 *time = mTTSSampleTime + mTTSDuration * (sampleIndex - mTTSSampleIndex);

 int32_t offset = mTable->getCompositionTimeOffset(sampleIndex);
 if ((offset < 0 && *time < (offset == INT32_MIN ?
            INT32_MAX : uint32_t(-offset))) ||
 (offset > 0 && *time > UINT32_MAX - offset)) {
        ALOGE("%u + %d would overflow", *time, offset);
 return ERROR_OUT_OF_RANGE;
 }
 if (offset > 0) {
 *time += offset;
 } else {
 *time -= (offset == INT32_MIN ? INT32_MAX : (-offset));
 }

